   296	
   297	/**
   298	 * There are 2 possibilities that we can receive via pusher for a user's typing/leaving status:
   299	 * 1. The "new" way from New Expensify is passed as {[login]: Boolean} (e.g. {yuwen@expensify.com: true}), where the value
   300	 * is whether the user with that login is typing/leaving on the report or not.
   301	 * 2. The "old" way from e.com which is passed as {userLogin: login} (e.g. {userLogin: bstites@expensify.com})
   302	 *
   303	 * This method makes sure that no matter which we get, we return the "new" format
   304	 */
   305	function getNormalizedStatus(typingStatus: Pusher.UserIsTypingEvent | Pusher.UserIsLeavingRoomEvent): ReportUserIsTyping {
   306	    let normalizedStatus: ReportUserIsTyping;
   307	
   308	    if (typingStatus.userLogin) {
   309	        normalizedStatus = {[typingStatus.userLogin]: true};
   310	    } else {
   311	        normalizedStatus = typingStatus;
   312	    }
   313	
   314	    return normalizedStatus;
   315	}
