   317	/** Initialize our pusher subscriptions to listen for someone typing in a report. */
   318	function subscribeToReportTypingEvents(reportID: string) {
   319	    if (!reportID) {
   320	        return;
   321	    }
   322	
   323	    // Make sure we have a clean Typing indicator before subscribing to typing events
   324	    Onyx.set(`${ONYXKEYS.COLLECTION.REPORT_USER_IS_TYPING}${reportID}`, {});
   325	
   326	    const pusherChannelName = getReportChannelName(reportID);
   327	    Pusher.subscribe(pusherChannelName, Pusher.TYPE.USER_IS_TYPING, (typingStatus) => {
   328	        // If the pusher message comes from OldDot, we expect the typing status to be keyed by user
   329	        // login OR by 'Concierge'. If the pusher message comes from NewDot, it is keyed by accountID
   330	        // since personal details are keyed by accountID.
   331	        const normalizedTypingStatus = getNormalizedStatus(typingStatus);
   332	        const accountIDOrLogin = Object.keys(normalizedTypingStatus)[0];
   333	
   334	        if (!accountIDOrLogin) {
   335	            return;
   336	        }
   337	
   338	        // Don't show the typing indicator if the user is typing on another platform
   339	        if (Number(accountIDOrLogin) === currentUserAccountID) {
   340	            return;
   341	        }
   342	
   343	        // Use a combo of the reportID and the accountID or login as a key for holding our timers.
   344	        const reportUserIdentifier = `${reportID}-${accountIDOrLogin}`;
   345	        clearTimeout(typingWatchTimers[reportUserIdentifier]);
   346	        Onyx.merge(`${ONYXKEYS.COLLECTION.REPORT_USER_IS_TYPING}${reportID}`, normalizedTypingStatus);
   347	
   348	        // Wait for 1.5s of no additional typing events before setting the status back to false.
   349	        typingWatchTimers[reportUserIdentifier] = setTimeout(() => {
   350	            const typingStoppedStatus: ReportUserIsTyping = {};
   351	            typingStoppedStatus[accountIDOrLogin] = false;
   352	            Onyx.merge(`${ONYXKEYS.COLLECTION.REPORT_USER_IS_TYPING}${reportID}`, typingStoppedStatus);
   353	            delete typingWatchTimers[reportUserIdentifier];
   354	        }, 1500);
   355	    }).catch((error: ReportError) => {
   356	        Log.hmmm('[Report] Failed to initially subscribe to Pusher channel', {errorType: error.type, pusherChannelName});
   357	    });
   358	}
